class DispatchJobService{static $inject=["$mdDialog","$document","DispatchData"];constructor($mdDialog,$document,DispatchData){this.$mdDialog=$mdDialog;this.$document=$document;this.DispatchData=DispatchData;this.pickCouriers=[];this.pickAllCouriers=[];this._fetchCouriersData()}_fetchCouriersData(){this._fetchActiveCouriersData();this._fetchAllCouriersData()}_fetchActiveCouriersData(){this.DispatchData.getActiveCouriers().then(data=>{this.pickCouriers=data})}_fetchAllCouriersData(){this.DispatchData.getAllCouriers().then(data=>{this.pickAllCouriers=data})}async dispatchJobByJobId(courierNumber,jobId){const job=this.DispatchData.getJobDetail(jobId);const selectedCourier=this.pickAllCouriers.find(c=>c.courierID===courierNumber);await this.dispatchJob(selectedCourier.id,job)}async dispatchJob(courierNumber,job){this._fetchActiveCouriersData();let foundCourier=this.pickCouriers.find(c=>c.id===courierNumber);if(foundCourier===undefined){const confirm=this._generateOfflineCourierDialog();try{await this.$mdDialog.show(confirm);foundCourier=this.pickAllCouriers.find(c=>c.id===courierNumber)}catch(error){console.log("User chose not to dispatch job as courier is offline")}}await this._dispatchJobsContinue(courierNumber,foundCourier,job)}_generateOfflineCourierDialog(){return this.$mdDialog.confirm().title("Courier Offline").textContent("Dispatch anyway?").ok("Yes").cancel("No")}async _dispatchJobsContinue(courierNumber,foundCourier,job){let jobs=[];const jobNumber=job.jobNo;if(job.courierData&&job.courierData.courierID!==null){this._showAlertMessage("Restore "+jobNumber+" prior to dispatching to another courier");return}if(job.dgClass!==null&&job.dgClass>0&&!foundCourier.dangerousGoods){this._showAlertMessage("DG job "+jobNumber+" can not be dispatched to courier "+courierNumber+" - doesn't have DGLicense.");return}if(job.dgClass!==null&&job.dgClass>0&&(job.DGLicenseExpiry===null||moment(foundCourier.dgLicenseExpiry)<moment().add(1,"days"))){this._showAlertMessage("Courier "+courierNumber+" doesn't have a DGLicense or license has expired.");return}jobs.push(job.id);await this.DispatchData.allocateJobs(foundCourier.courierID,ContactID,jobs)}_showAlertMessage(textContent){const alert=this.$mdDialog.alert().parent(angular.element(this.$document.body)).clickOutsideToClose(true).title("Message").textContent(textContent).ariaLabel("Alert").ok("OK");this.$mdDialog.show(alert)}}angular.module("uDispatch").service("dispatchJobService",DispatchJobService);